from dataclasses import dataclass

@dataclass
class PlayerStats:
    health: int = 100
    armor: int = 0

    def __post_init__(self) -> None:
        if not 0 <= self.health <= 100:
            raise ValueError("health must be between 0 and 100")
        if not 0 <= self.armor <= 100:
            raise ValueError("armor must be between 0 and 100")

    def apply_damage(self, amount: int) -> int:
        if amount < 0:
            raise ValueError("amount must be non-negative")
        absorbed = min(self.armor, amount)
        self.armor -= absorbed
        self.health = max(0, self.health - (amount - absorbed))
        return self.health

